<?php
require_once __DIR__.'/app/lib/Db.php';require_once __DIR__.'/app/lib/Security.php';require_once __DIR__.'/app/lib/Entitlements.php';$pdo=Db::pdo();Security::start();$u=Security::user();if(!$u){header('Location:/login?next='.rawurlencode('/rfp-builder'));exit;}$ctx=Entitlements::context($pdo,$u);$csrf=Security::csrf();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>RFP Builder | TechSelectAI</title><style>body{font-family:Inter,Arial;background:#f6f8fb;color:#172033;margin:0}main{max-width:1100px;margin:auto;padding:24px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:16px;margin:12px 0}input,textarea{width:100%;box-sizing:border-box;padding:9px;border:1px solid #cbd5e1;border-radius:8px}textarea{min-height:110px}button{padding:9px 12px;border:0;border-radius:8px;background:#1d4ed8;color:#fff;cursor:pointer}.muted{color:#64748b}.section{margin:12px 0}.warn{background:#fff7ed;padding:10px;border-radius:10px}</style></head><body><main><h1>RFP Builder</h1><p class="muted">Generate an editable software-selection RFP from a saved project and its latest decision matrix.</p><div class="warn">TechSelectAI stops at evaluation/RFP preparation. Supplier response portals, approvals, PO creation, invoicing and procurement execution are outside scope.</div><div class="card"><label>Selection Project ID</label><input id="pid" type="number"><p><button onclick="preview()">Preview</button><?php if($ctx['features']['rfp_generator']): ?> <button onclick="generate()">Generate editable RFP</button><?php endif; ?></p></div><div id="out"></div></main><script>const csrf=<?=json_encode($csrf)?>;async function req(url,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json','X-CSRF-Token':csrf};let r=await fetch(url,opt),d=await r.json().catch(()=>({error:'invalid_response'}));if(!r.ok)throw new Error(d.error||'request_failed');return d}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}function render(d,editable){let r=d.rfp?.sections||d.rfp?.sections_json||{};document.getElementById('out').innerHTML='<div class="card">'+Object.entries(r).map(([k,v])=>`<div class="section"><h3>${esc(k.replaceAll('_',' '))}</h3><textarea ${editable?'':'disabled'} data-k="${esc(k)}">${esc(typeof v==='string'?v:JSON.stringify(v,null,2))}</textarea></div>`).join('')+'</div>'}async function preview(){try{let d=await req('/api/rfps/project/'+pid.value+'/preview');render(d,false)}catch(e){alert(e.message)}}async function generate(){try{let d=await req('/api/rfps/project/'+pid.value,{method:'POST',body:JSON.stringify({})});render(d,true);alert('RFP draft created #'+d.id)}catch(e){alert(e.message)}}</script></body></html>